import sys
N = int(input())
sys.setrecursionlimit(1000000)

def t(l, r):
	if l + 1 == r:
		return (1, l)
	else:
		m = (l + r) // 2
		e = t(l, m)
		d = t(m, r)
		return (e[0] * d[1] + d[0], e[1] * d[1])

def calc(a, b, n):
	if n == 0:
		return 0
	k = a // b
	a -= k * b
	m = a * n // b
	return k * (n * (n + 1) >> 1) + m * n - calc(b, a, m)
print(N * (N + 1) + calc(*t(2, 3505), N))
